    /// <summary>
    /// Set the annotation format (Compact / Full / Reference) and re-render the
    /// active view's existing annotations in it. The three panel buttons
    /// (SldAnnotate_Format_Compact / _Full / _Reference) set
    /// <see cref="PendingFormat"/> first so each applies its own format; the plain
    /// SldAnnotate_Format tag shows the chooser. Before, all four opened the chooser.
    /// </summary>
    [Transaction(TransactionMode.Manual)]
    [Regeneration(RegenerationOption.Manual)]
    public class SldAnnotationFormatCommand : IExternalCommand
    {
        /// <summary>Consumed by the next Execute; null means "ask".</summary>
        internal static SldAnnotFormat? PendingFormat { get; set; }

        public Result Execute(ExternalCommandData cd, ref string msg, ElementSet els)
        {
            var ctx = ParameterHelpers.GetContext(cd);
            if (ctx == null) return Result.Failed;

            SldAnnotFormat chosen;
            var pending = PendingFormat;
            PendingFormat = null;
            if (pending.HasValue)
            {
                chosen = pending.Value;
            }
            else
            {
                var current = SldAnnotationEngine.CurrentFormat;
                var td = new TaskDialog("STING SLD — Annotation Format")
                {
                    MainInstruction = $"Current format: {current}",
                    MainContent = "Compact — cable/current/breaker on one line (e.g. 4mm² / 32A / B32)\n" +
                                  "Full    — verbose labels for each field (e.g. Cable: 4mm² | Ib: 32A)\n" +
                                  "Reference — circuit ref + panel name only",
                    CommonButtons = TaskDialogCommonButtons.Cancel,
                };
                td.AddCommandLink(TaskDialogCommandLinkId.CommandLink1, "Compact");
                td.AddCommandLink(TaskDialogCommandLinkId.CommandLink2, "Full");
                td.AddCommandLink(TaskDialogCommandLinkId.CommandLink3, "Reference only");
                var result = td.Show();
                if (result == TaskDialogResult.CommandLink1) chosen = SldAnnotFormat.Compact;
                else if (result == TaskDialogResult.CommandLink2) chosen = SldAnnotFormat.Full;
                else if (result == TaskDialogResult.CommandLink3) chosen = SldAnnotFormat.Reference;
                else return Result.Cancelled;
            }

            SldAnnotationEngine.CurrentFormat = chosen;

            var view = ctx.UIDoc.ActiveView;
            int existing = view == null ? 0 : SldAnnotationEngine.CollectExistingAnnotations(ctx.Doc, view).Count;
            string report = $"Format set to: {chosen}.";
            if (existing > 0)
            {
                (int Changed, int Orphaned, int Empty) r;
                using (var t = new Transaction(ctx.Doc, "STING SLD Annotation Format"))
                {
                    t.Start();
                    r = SldAnnotationEngine.UpdateAnnotations(ctx.Doc, view, chosen);
                    t.Commit();
                }
                report += $"\nRe-rendered {r.Changed} of {existing} annotation(s) in this view.";
                if (r.Empty > 0) report += $"\n{r.Empty} left as they were — no value to show in {chosen} format.";
                if (r.Orphaned > 0) report += $"\n{r.Orphaned} point at an element that no longer exists.";
            }
            else
            {
                report += "\nNo SLD annotations in this view yet; new annotations will use this format.";
            }
            StingLog.Info($"SldAnnotationFormat: {chosen}, {existing} existing");
            TaskDialog.Show("STING SLD — Format", report);
            return Result.Succeeded;
        }
    }

    /// <summary>Refresh existing SLD annotations from current parameter values.</summary>
    [Transaction(TransactionMode.Manual)]
    [Regeneration(RegenerationOption.Manual)]
    public class SldUpdateFromCalcsCommand : IExternalCommand
    {
        public Result Execute(ExternalCommandData cd, ref string msg, ElementSet els)
        {
            var ctx = ParameterHelpers.GetContext(cd);
            if (ctx == null) return Result.Failed;

            var view = ctx.UIDoc.ActiveView;
            var existing = SldAnnotationEngine.CollectExistingAnnotations(ctx.Doc, view);
            if (existing.Count == 0)
            {
                TaskDialog.Show("STING SLD — Update",
                    "No STING SLD annotations found in this view.\nRun 'SLD Annotate All' first.");
                return Result.Succeeded;
            }

            (int Changed, int Orphaned, int Empty) r;
            using (var t = new Transaction(ctx.Doc, "STING SLD Update Annotations"))
            {
                t.Start();
                r = SldAnnotationEngine.UpdateAnnotations(ctx.Doc, view, SldAnnotationEngine.CurrentFormat);
                t.Commit();
            }
            string report = $"Updated {r.Changed} of {existing.Count} annotation(s) from current values " +
                            $"({existing.Count - r.Changed - r.Orphaned - r.Empty} already current).";
            if (r.Empty > 0) report += $"\n{r.Empty} now have no value; their old text was kept.";
            if (r.Orphaned > 0) report += $"\n{r.Orphaned} point at an element that no longer exists — use Clear and re-annotate.";
            TaskDialog.Show("STING SLD — Update", report);
            return Result.Succeeded;
        }
    }

    /// <summary>Show / hide STING SLD annotations in the active view.</summary>
    [Transaction(TransactionMode.Manual)]
    [Regeneration(RegenerationOption.Manual)]
    public class SldAnnotationToggleCommand : IExternalCommand
    {
        public Result Execute(ExternalCommandData cd, ref string msg, ElementSet els)
        {
            var ctx = ParameterHelpers.GetContext(cd);
            if (ctx == null) return Result.Failed;

            var view = ctx.UIDoc.ActiveView;
            var existing = SldAnnotationEngine.CollectExistingAnnotations(ctx.Doc, view);
            if (existing.Count == 0)
            {
                TaskDialog.Show("STING SLD — Toggle", "No STING SLD annotations found in this view.");
                return Result.Succeeded;
            }

            var td = new TaskDialog("STING SLD — Toggle Visibility")
            {
                MainInstruction = $"{existing.Count} SLD annotation(s) found.",
                CommonButtons = TaskDialogCommonButtons.Cancel,
            };
            td.AddCommandLink(TaskDialogCommandLinkId.CommandLink1, "Show (remove halftone)");
            td.AddCommandLink(TaskDialogCommandLinkId.CommandLink2, "Hide (halftone / grey out)");

            var result = td.Show();
            bool show = result == TaskDialogResult.CommandLink1;
            bool hide = result == TaskDialogResult.CommandLink2;
            if (!show && !hide) return Result.Succeeded;

            int n;
            using (var t = new Transaction(ctx.Doc, "STING SLD Toggle Visibility"))
            {
                t.Start();
                n = SldAnnotationEngine.ToggleAnnotationVisibility(ctx.Doc, view, show);
                t.Commit();
            }
            TaskDialog.Show("STING SLD — Toggle",
                $"{n} of {existing.Count} annotation(s) {(show ? "shown" : "halftoned")}.");
            return Result.Succeeded;
        }
    }

    /// <summary>Remove all STING SLD annotations from the active view.</summary>
    [Transaction(TransactionMode.Manual)]
    [Regeneration(RegenerationOption.Manual)]
    public class SldAnnotationClearCommand : IExternalCommand
    {
        public Result Execute(ExternalCommandData cd, ref string msg, ElementSet els)
        {
            var ctx = ParameterHelpers.GetContext(cd);
            if (ctx == null) return Result.Failed;

            var view = ctx.UIDoc.ActiveView;
            var existing = SldAnnotationEngine.CollectExistingAnnotations(ctx.Doc, view);
            if (existing.Count == 0)
            {
                TaskDialog.Show("STING SLD — Clear", "No STING SLD annotations found in this view.");
                return Result.Succeeded;
            }

            var confirm = TaskDialog.Show("STING SLD — Clear Annotations",
                $"Delete {existing.Count} SLD annotation(s) from '{view.Name}'?\n" +
                "Only notes placed by the SLD annotate commands are removed.",
                TaskDialogCommonButtons.Yes | TaskDialogCommonButtons.No);
            if (confirm != TaskDialogResult.Yes) return Result.Succeeded;

            int deleted = 0;
            using (var t = new Transaction(ctx.Doc, "STING SLD Clear Annotations"))
            {
                t.Start();
                foreach (var a in existing)
                {
                    try { ctx.Doc.Delete(a.Note.Id); deleted++; }
                    catch (Exception ex) { StingLog.Warn($"SldAnnotationClear: {ex.Message}"); }
                }
                t.Commit();
            }
            TaskDialog.Show("STING SLD — Clear", $"Removed {deleted} of {existing.Count} annotation(s).");
            return Result.Succeeded;
        }
    }

    /// <summary>Audit report: which elements have annotations vs missing.</summary>
    [Transaction(TransactionMode.ReadOnly)]
    [Regeneration(RegenerationOption.Manual)]
    public class SldAnnotationAuditCommand : IExternalCommand
    {
        public Result Execute(ExternalCommandData cd, ref string msg, ElementSet els)
        {
            var ctx = ParameterHelpers.GetContext(cd);
            if (ctx == null) return Result.Failed;

            var view = ctx.UIDoc.ActiveView;
            var annotatable = SldAnnotationEngine.CollectAnnotatableElements(ctx.Doc, view);
            var existing    = SldAnnotationEngine.CollectExistingAnnotations(ctx.Doc, view);

            var annotatedIds = new HashSet<string>(existing.Select(a => a.AnchorUniqueId));
            int annotated   = annotatable.Count(el => annotatedIds.Contains(el.UniqueId));
            int unannotated = annotatable.Count - annotated;
            int orphaned    = existing.Count(a => ctx.Doc.GetElement(a.AnchorUniqueId) == null);

            string report = $"SLD Annotation Audit — '{view.Name}'\n\n" +
                $"Elements with electrical values:      {annotatable.Count}\n" +
                $"  Annotated:                          {annotated}\n" +
                $"  Missing annotations:                {unannotated}\n" +
                $"STING SLD notes in view:              {existing.Count}\n" +
                (orphaned > 0 ? $"  Pointing at deleted elements:       {orphaned}\n" : "") +
                $"Current annotation format:            {SldAnnotationEngine.CurrentFormat}\n\n" +
                (annotatable.Count == 0
                    ? "No element in this view carries SLD values — annotate has nothing to work from."
                    : unannotated > 0
                        ? "Run 'SLD Annotate All' to fill missing annotations."
                        : "All annotatable elements have annotations.");
            TaskDialog.Show("STING SLD — Annotation Audit", report);
            return Result.Succeeded;
        }
    }
}
